      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });

    expect(forAdmin.items).toHaveLength(1);
    expect(forViewer.items).toHaveLength(1);
    expect(forAdmin.items[0]?.kind).toBe("comment_mention");
  });

  // The actor who caused the event is not notified about their own action.
  it("does not notify the actor about their own action", async () => {
    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.member, tenant.userIds.admin],
      {
        title: "New comment",
        body: "Someone commented",
        href: "/issues/x",
        actorId: tenant.userIds.member,
      },
    );

    expect(rows).toHaveLength(1);
    expect(rows[0]?.recipientId).toBe(tenant.userIds.admin);
  });

  // NotificationPreference.email === false suppresses the email channel only.
  it("honours the per-kind email preference", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_assigned",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "Assigned",
      body: "You were assigned",
      href: "/issues/y",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toEqual(["in_app"]);
  });

  // digestOnly routes the entry to the digest instead of an immediate email.
  it("queues a digestOnly notification for the digest instead of sending", () => {
    const flagsWithDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "growth",
      role: null,
      overrides: undefined,
    };

    const channels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithDigest,
    );

    // The org's plan includes the digest_email flag, so the entry is still
    // routed to the "email" channel — it will go out with the digest run
    // rather than never leaving the in-app row.
    expect(channels).toEqual(["in_app", "email"]);
  });

  // isEnabled("digest_email", …) gates the digest channel by plan.
  it("skips the digest channel when the digest_email flag is off", () => {
    const flagsWithoutDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "free",
      role: null,
      overrides: undefined,
    };

    const digestOnlyChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithoutDigest,
    );

    // Without the plan flag, a digestOnly preference loses the email channel
    // entirely (the org has no digest run to defer it to).
    expect(digestOnlyChannels).toEqual(["in_app"]);

    // A non-digestOnly preference is unaffected by the flag.
    const immediateChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: false,
      },
      flagsWithoutDigest,
    );
    expect(immediateChannels).toEqual(["in_app", "email"]);
  });

  // in_app is always recorded, even when email delivery is suppressed.
  it("always records the in-app notification", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "member_joined",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "member_joined", [tenant.userIds.viewer], {
      title: "Member joined",
      body: "A member joined",
      href: "/settings/members",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toContain("in_app");

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["member_joined"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  // Notifications carry the org id and are only visible inside that tenant.
  it("scopes notifications to the recipient's organization", async () => {
    const other = await createTenant("notify-other", "growth");

    await notify(tenant.org.id, "member_joined", [tenant.userIds.owner], {
      title: "Member joined",
      body: "Welcome",
      href: "/settings/members",
      actorId: null,
    });

    await expect(
      listNotifications(other.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);
  });
});
/**
 * Runs only for orgs whose digest hour has arrived and whose plan includes it.
 *
 * Owner C implements `@/server/jobs/digest-email-job`. The window arithmetic
 * itself is covered by `tests/lib/date.test.ts`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as emailService from "@/server/services/email-service";
import * as featureFlagService from "@/server/services/feature-flag-service";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { PlanId } from "@/types/billing";

let cleanup: () => void;

/** `2026-06-01T0{hour}:00:00.000Z` — every test gets its own hour so a scan
 * driven by one test's `now` never also matches another test's org. */
function nowAtHour(hour: number): Date {
  return new Date(Date.UTC(2026, 5, 1, hour, 0, 0, 0));
}

/** Creates a tenant on `plan` whose digest fires only at `digestHourUtc`, and
 * registers it with the usage rollup so `listOrgIdsForRollup` finds it. */
async function makeTenant(
  slug: string,
  digestHourUtc: number,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const tenant = await createTenant(slug, plan);
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { digestHourUtc },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

/** Subscribes a member to the digest by setting one `digestOnly` preference. */
async function subscribeToDigest(tenant: Tenant): Promise<void> {
  await preferenceRepo.upsertPreference({
    orgId: tenant.org.id,
    userId: tenant.userIds.member,
    kind: "comment_created",
    inApp: false,
    email: false,
    digestOnly: true,
  });
}

async function insertNotificationAt(
  tenant: Tenant,
  at: Date,
  title: string,
): Promise<void> {
  vi.useFakeTimers();
  vi.setSystemTime(at);
  try {
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title,
      body: title,
      href: "/issues/1",
      actorId: null,
      channels: ["email"],
    });
  } finally {
    vi.useRealTimers();
  }
}

/** Pulls a `<td>key</td><td>value</td>` cell out of the generic email table. */
function cell(html: string, key: string): string | null {
  const match = html.match(new RegExp(`<td>${key}</td><td>([^<]*)</td>`));
  return match?.[1] ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("jobs/digest-email-job", () => {
  it("uses the org's configured digest hour to pick the window", async () => {
    const now = nowAtHour(1);
    const tenant = await makeTenant("digest-window", 1);
    await subscribeToDigest(tenant);

    await insertNotificationAt(tenant, new Date(now.getTime() - 12 * 3_600_000), "Recent update");
    await insertNotificationAt(tenant, new Date(now.getTime() - 30 * 3_600_000), "Stale update");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe("1");
    expect(cell(html, "headline")).toBe("Recent update");
  });

  it("skips an org whose digest hour has not arrived", async () => {
    const tenant = await makeTenant("digest-hour-not-yet", 2);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(nowAtHour(2).getTime() - 3_600_000), "Fresh");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    // A run at an hour that does not match the org's configured hour.
    await runDigestEmailJob(nowAtHour(3));

    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("skips an org whose plan does not include digest_email", async () => {
    const now = nowAtHour(4);
    const tenant = await makeTenant("digest-free-plan", 4, "free");
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Fresh");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("sends nothing to a recipient with an empty window", async () => {
    const now = nowAtHour(5);
    const tenant = await makeTenant("digest-empty-window", 5);
    await subscribeToDigest(tenant);
    // Nothing unread inside the window at all.

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    const result = await runDigestEmailJob(now);

    expect(sendSpy).not.toHaveBeenCalled();
    expect(result.processed).toBe(0);
  });

  it("caps the entries at DIGEST_MAX_ENTRIES", async () => {
    const now = nowAtHour(6);
    const tenant = await makeTenant("digest-cap", 6);
    await subscribeToDigest(tenant);

    for (let i = 0; i < DIGEST_MAX_ENTRIES + 5; i += 1) {
      await insertNotificationAt(
        tenant,
        new Date(now.getTime() - (i + 1) * 1_000),
        `Update ${i}`,
      );
    }

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe(String(DIGEST_MAX_ENTRIES));
  });

  it("does not resend a digest for an already-covered window", async () => {
    const now = nowAtHour(7);
    const tenant = await makeTenant("digest-no-resend", 7);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Once");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);
    expect(sendSpy).toHaveBeenCalledTimes(1);

    await runDigestEmailJob(now);
    expect(sendSpy).toHaveBeenCalledTimes(1);
  });

  it("constructs its own actor rather than reading cookies", async () => {
    const now = nowAtHour(8);
    const tenant = await makeTenant("digest-own-actor", 8);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Owns its actor");

    vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    const contextSpy = vi.spyOn(featureFlagService, "buildFlagContext");

    await runDigestEmailJob(now);

    expect(contextSpy).toHaveBeenCalledWith(
      null,
      expect.objectContaining({ id: tenant.org.id }),
    );
  });
});
/**
 * Deterministic factories for actors, orgs, projects, issues and comments
 * used across the suite.
 *
 * Every factory seeds from the same `idFactory`, so a test that does not care
 * about ids gets stable ones, and a test that does can override them. All
 * default rows live in `ORG_A` — cross-tenant tests pass `orgId: ORG_B`.
 */
import { idFactory } from "@/lib/id";
import type { LimitCheck } from "@/types/billing";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IsoTimestamp,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
